import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
import { getDashboard } from "./dashboard";
import { readEvals } from "./evals";
import { KPIS } from "./kpis";
import type { Query } from "./query";

/** docs/quality/METRICS.md as text. Generated from the same queries as the dashboard; never edited by hand. */
export async function renderMetrics(q: Query, scopeLabel: string, root = process.cwd()): Promise<string> {
  const [d, evals] = await Promise.all([getDashboard(q), readEvals(root)]);
  const out = [
    "# Metrics",
    "",
    "<!-- Generated by `npm run metrics:report`. Do not edit by hand: change lib/analytics/kpis.ts or the query and regenerate. -->",
    "",
    `Generated at: ${q.now.toISOString()}`,
    `Window: ${q.from.toISOString()} to ${q.to.toISOString()} (UTC, buckets per ${q.bucket})`,
    `Scope: ${scopeLabel}`,
    "",
    "Every figure below comes from one function in `lib/analytics/`, the same one the `/analytics` dashboard calls. Money is stored as integer cents, cost as integer micro-dollars, time as milliseconds; they are divided only when printed.",
    "",
  ];
  for (const k of KPIS) {
    out.push(
      `## ${k.title}`,
      "",
      `- **Definition:** ${k.definition}`,
      `- **Formula:** ${k.formula}`,
      `- **Source:** ${k.source}`,
      `- **Counts:** ${k.counts}`,
      `- **Does not count:** ${k.excludes}`,
      `- **How to read it:** ${k.read}`,
      "",
      "Latest values:",
      "",
      k.values(d, evals),
      "",
    );
  }
  return out.join("\n");
}

export async function writeMetrics(file: string, q: Query, scopeLabel: string, root = process.cwd()): Promise<string> {
  const text = await renderMetrics(q, scopeLabel, root);
  await mkdir(path.dirname(file), { recursive: true });
  await writeFile(file, text);
  return text;
}
